const rows = $input.all().map(i => i.json);
const sources = [];
for (const row of rows) {
  if (Array.isArray(row.items)) {
    for (const x of row.items.slice(0, 8)) sources.push({type:'GitHub', title:x.full_name, description:x.description || '', url:x.html_url, score:x.stargazers_count || 0});
  }
  if (Array.isArray(row.hits)) {
    for (const x of row.hits.slice(0, 12)) sources.push({type:'News', title:x.title || x.story_title || '', description:'', url:x.url || x.story_url || ('https://news.ycombinator.com/item?id=' + x.objectID), score:x.points || 0});
  }
}
const sourceText = sources.map((x,i) => `${i+1}. [${x.type}] ${x.title} | 관심도 ${x.score} | ${x.description} | ${x.url}`).join('\n');
return [{json:{source_count:sources.length, sources, source_text:sourceText, report_date:new Intl.DateTimeFormat("en-CA", { timeZone: "Asia/Seoul", year: "numeric", month: "2-digit", day: "2-digit" }).format(new Date())}}];

const base=$('트렌드 정리').item.json;
const text=String($json.candidates?.[0]?.content?.parts?.map(p=>p.text||'').join('')||'').trim();
return [{json:{...base,provider:'gemini',model:'gemini-2.5-flash',fallback_used:false,error_summary:'',report_text:'추론: Gemini / gemini-2.5-flash

'+text}}];

const base=$('Ollama fallback 요청 준비').item.json;
const text=String($json.message?.content||'').trim();
const fallbackError=String($json.error?.message||$json.error?.description||'').slice(0,500);
const body=text || '분석 결과를 생성하지 못했습니다. Gemini와 로컬 Ollama fallback을 모두 확인해야 합니다.';
return [{json:{...base,provider:'ollama-local',model:'qwen3.5:4b',fallback_used:true,error_summary:[base.gemini_error,fallbackError].filter(Boolean).join(' | '),report_text:'추론: Ollama fallback / qwen3.5:4b
Gemini 오류: '+base.gemini_error+'

'+body}}];
